mkdir -p deploy .github/workflows && cat > astro.config.mjs <<'EOF'
// @ts-check
import { defineConfig } from "astro/config";

import preact from "@astrojs/preact";

// https://astro.build/config
export default defineConfig({
  // Public URL of the deployed site, used for canonical/RSS links.
  // Set SITE_URL at build time (see fly.toml [build.args]).
  site: process.env.SITE_URL || "https://example.com",
  integrations: [preact()],
});
EOF
cat > .dockerignore <<'EOF'
.git
.github
.vscode
.astro
node_modules
dist
.env
.env.*
npm-debug.log*
Dockerfile
fly.toml
EOF
cat > Dockerfile <<'EOF'
# syntax=docker/dockerfile:1

# ---- Build stage: compile the Astro site to static files ----
FROM node:22-bookworm-slim AS build
WORKDIR /app

COPY package.json package-lock.json ./
RUN npm ci --no-audit --no-fund

COPY . .
# Public URL baked into canonical/RSS links (passed from fly.toml [build.args]).
ARG SITE_URL
RUN npm run build

# ---- Runtime stage: serve dist/ with nginx as a non-root user ----
FROM nginxinc/nginx-unprivileged:stable-alpine

COPY deploy/nginx.conf /etc/nginx/conf.d/default.conf
COPY --from=build /app/dist /usr/share/nginx/html

EXPOSE 8080
# The base image's CMD runs nginx in the foreground; if it dies, the
# container exits and Fly's restart policy brings the machine back.
EOF
cat > deploy/nginx.conf <<'EOF'
# Server config for the Astro static build. Installed as
# /etc/nginx/conf.d/default.conf in nginxinc/nginx-unprivileged.

# One JSON object per request on stdout -> readable via `fly logs`.
log_format json_access escape=json
  '{"time":"$time_iso8601",'
  '"client_ip":"$remote_addr",'
  '"method":"$request_method",'
  '"uri":"$request_uri",'
  '"status":$status,'
  '"bytes":$body_bytes_sent,'
  '"duration_s":$request_time,'
  '"referer":"$http_referer",'
  '"user_agent":"$http_user_agent",'
  '"edge_region":"$http_fly_region",'
  '"request_id":"$http_fly_request_id"}';

# Fly's proxy passes the real client address in Fly-Client-IP.
set_real_ip_from 0.0.0.0/0;
set_real_ip_from ::/0;
real_ip_header Fly-Client-IP;

server {
  listen 8080;
  listen [::]:8080;
  server_name _;

  root /usr/share/nginx/html;
  index index.html;

  access_log /dev/stdout json_access;
  error_log /dev/stderr warn;

  server_tokens off;
  # Emit relative Location headers, so redirects never leak the
  # internal port (:8080) or the http scheme behind Fly's TLS proxy.
  absolute_redirect off;

  gzip on;
  gzip_vary on;
  gzip_min_length 1024;
  gzip_types text/css application/javascript application/json
             application/xml application/rss+xml image/svg+xml text/plain;

  # TLS is terminated at Fly's edge and fly.toml sets force_https,
  # so every browser-facing response is HTTPS.
  add_header Strict-Transport-Security "max-age=31536000" always;
  add_header X-Content-Type-Options "nosniff" always;
  add_header X-Frame-Options "DENY" always;
  add_header Referrer-Policy "strict-origin-when-cross-origin" always;

  # Used by Fly health checks; kept out of the access log.
  location = /healthz {
    access_log off;
    default_type text/plain;
    return 200 "ok\n";
  }

  # Astro's fingerprinted bundles: safe to cache forever.
  location /_astro/ {
    expires max;
    try_files $uri =404;
  }

  # Pages, RSS, favicon: always revalidate so deploys show up immediately.
  location / {
    expires -1;
    try_files $uri $uri/index.html $uri.html =404;
  }

  # Picked up automatically if src/pages/404.astro is added.
  error_page 404 /404.html;
}
EOF

cd /tmp/nginx-pkg && curl -sSLO https://deb.debian.org/debian/pool/main/n/nginx/nginx-common_1.22.1-9+deb12u9_all.deb && dpkg -x nginx-common_*.deb root && mkdir -p /tmp/nginx-run/{conf.d,logs,tmp} && cp root/etc/nginx/mime.types /tmp/nginx-run/ \
&& sed 's#/usr/share/nginx/html#/work/repo/dist#' /work/repo/deploy/nginx.conf > /tmp/nginx-run/conf.d/default.conf \
&& cat > /tmp/nginx-run/nginx.conf <<'EOF'
worker_processes auto;
error_log stderr notice;
pid /tmp/nginx-run/nginx.pid;
events { worker_connections 1024; }
http {
  include /tmp/nginx-run/mime.types;
  default_type application/octet-stream;
  client_body_temp_path /tmp/nginx-run/tmp/body;
  proxy_temp_path /tmp/nginx-run/tmp/proxy;
  fastcgi_temp_path /tmp/nginx-run/tmp/fcgi;
  uwsgi_temp_path /tmp/nginx-run/tmp/uwsgi;
  scgi_temp_path /tmp/nginx-run/tmp/scgi;
  access_log /tmp/nginx-run/logs/default-access.log;
  sendfile on;
  keepalive_timeout 65;
  include /tmp/nginx-run/conf.d/*.conf;
}
EOF
cd /tmp/nginx-run && /tmp/nginx-pkg/root/usr/sbin/nginx -p /tmp/nginx-run -c /tmp/nginx-run/nginx.conf -t 2>&1
